import {createCreationUI} from './creation-ui.js';
export function createInternalMarketingUI(shared){
 const {api,esc,getBoot,openDialog,closeDialog,toast,uploadFile}=shared;let active=false,epoch=0,data=null,S=null,tab='create';
 const endpoint=part=>'/api/portal/'+encodeURIComponent(S.company.id)+'/'+part;
 const creation=createCreationUI({api,esc,toast,uploadFile,endpoint,getState:()=>S,refresh:async()=>{S=await api(endpoint('state'));}});
 const request=d=>api('/api/portal/internal-marketing','POST',d);
 function page(){return '<section class="page-heading"><div><p class="overline">MARKETING DA HELPU</p><h1>É hora de mostrar o que fazemos.</h1><p>Criação, programação e resultados exclusivos de @helpumarketing.</p></div></section><div id="internal-marketing"></div>';}
 async function load(){const t=++epoch;try{const next=await api('/api/portal/internal-marketing');let state=null;if(next.configured)state=await api('/api/portal/'+encodeURIComponent(next.orgId)+'/state');if(!active||t!==epoch)return;data=next;S=state;paint();}catch(e){if(active&&t===epoch)document.querySelector('#internal-marketing').innerHTML='<p role="alert">'+esc(e.message)+'</p><button class="p-button secondary" data-marketing="refresh">Tentar novamente</button>';}}
 const btn=(label,act,id='')=>`<button class="p-button secondary" data-marketing="${act}" data-id="${esc(id)}">${label}</button>`;
 function paint(){const host=document.querySelector('#internal-marketing');if(!active||!host)return;creation.mount('');if(!data.configured){host.innerHTML=`<section class="admin-box"><h2>Defina a empresa interna</h2><p>Escolha o cadastro da própria Helpu. Esta área publicará somente em @helpumarketing e terá criação sem franquia interna.</p><form id="marketing-setup"><label class="p-field">Empresa da Helpu<select name="orgId">${getBoot().companies.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="checkline"><input type="checkbox" name="confirmed" required> Este é o cadastro interno da Helpu, não de um cliente.</label><button class="p-button primary">Preparar operação da Helpu</button><p role="alert" data-marketing-error></p></form></section>`;return;}
 host.innerHTML=`<section class="admin-box internal-account"><div><strong>@helpumarketing</strong><p>${esc(S.company.name)} · ${S.company.policy.dailyMedia==='unlimited'?'Criação sem franquia interna':'Liberação interna encerrada'}</p><small>O uso dos provedores continua sendo cobrado. Clientes mantêm publicação manual ou assistida.</small></div><div>${btn('Conectar Instagram','connect')}${btn('Verificar conta','verify')}<p>${data.connection.username?'Conexão salva: @'+esc(data.connection.username):'Instagram ainda não conectado.'}</p></div></section><nav class="client-tabs" aria-label="Marketing da Helpu">${[['create','Criar conteúdo'],['schedule','Programação'],['results','Desempenho']].map(([v,l])=>`<button class="p-button ${tab===v?'primary':'secondary'}" data-marketing-tab="${v}">${l}</button>`).join('')}${btn('Atualizar','refresh')}</nav><div id="internal-content">${tab==='create'?creation.page():tab==='schedule'?schedule():results()}</div>`;if(tab==='create')creation.mount('create');}
 function schedule(){return `<section class="admin-box"><h2>Arte aprovada. Próximo passo: publicar.</h2><p>Selecione uma criação aprovada e revise a legenda e o horário antes de autorizar o envio. O cliente não tem acesso a esta função.</p>${!data.storageReady?'<p role="status">A hospedagem precisa de armazenamento privado configurado para disponibilizar a mídia ao Instagram.</p>':''}<div class="internal-ready">${data.creations.map(c=>`<article><strong>${esc(c.prompt.slice(0,120))}</strong><span>${esc(c.format)}</span>${btn('Revisar e programar','schedule',c.id)}</article>`).join('')||'<p>As criações aparecerão aqui depois que você aprovar a prévia na aba Criar conteúdo.</p>'}</div></section><section class="admin-box"><h2>Agenda de publicações</h2>${data.posts.map(p=>`<article class="client-list-row"><strong>${esc(p.title)}</strong><span>${new Date(p.publishAt).toLocaleString('pt-BR')} · ${esc(({queued:'Programado',working:'Processando',waiting_provider:'Instagram processando',succeeded:'Publicado e conferido',failed:'Falha',blocked:'Precisa de ajuste',uncertain:'Confirmar no Instagram',canceled:'Cancelado'})[p.job?.state]||'Aguardando fila')}</span>${p.job?.error?'<p role="alert">'+esc(p.job.error)+'</p>':''}${['queued','waiting_provider'].includes(p.job?.state)?btn('Cancelar programação','cancel',p.id):''}${p.permalink?`<a href="${esc(p.permalink)}" target="_blank" rel="noopener">Ver publicação ↗</a>`:''}</article>`).join('')||'<p>Nenhuma publicação programada.</p>'}</section>`;}
 function results(){const labels={reach:'Contas alcançadas',views:'Visualizações',likes:'Curtidas',comments:'Comentários',saved:'Salvamentos',shares:'Compartilhamentos'};return `<section class="admin-box"><h2>O que o conteúdo está entregando</h2><p>Dados reais das publicações feitas por esta área. Leituras automáticas previstas após 1 hora, 24 horas e 7 dias, conforme disponibilidade do Instagram. Você também pode atualizar manualmente. Métrica indisponível não é tratada como zero.</p>${data.posts.filter(p=>p.verifiedAt).map(p=>`<article class="internal-result"><h3>${esc(p.title)}</h3><div class="client-stats">${(p.metrics?.metrics||[]).map(m=>`<span>${esc(labels[m.name]||m.name)}<strong>${m.value.toLocaleString('pt-BR')}</strong></span>`).join('')}</div><p>${p.metrics?'Leitura em '+new Date(p.metrics.observedAt).toLocaleString('pt-BR'):'Métricas ainda não disponíveis.'}</p>${(p.metrics?.unavailable||[]).map(m=>`<small>${esc(labels[m.name]||m.name)}: ${esc(m.reason)}</small>`).join('<br>')}${performance(p)}${btn('Atualizar desempenho','metrics',p.id)}</article>`).join('')||'<p>O desempenho aparecerá após a primeira publicação confirmada.</p>'}</section>`;}
 function performance(p){const m=p.metrics?.metrics||[],value=k=>m.find(x=>x.name===k)?.value,reach=value('reach'),saved=value('saved'),shares=value('shares');const earlier=(p.metricsHistory||[]).at(-2),prior=earlier?.metrics.find(x=>x.name==='reach')?.value;return '<p class="micro-copy">'+(Number.isFinite(reach)&&reach>0&&Number.isFinite(saved)?'Salvamentos por conta alcançada: '+(saved/reach*100).toFixed(1)+'%. ':'')+(Number.isFinite(reach)&&reach>0&&Number.isFinite(shares)?'Compartilhamentos por conta alcançada: '+(shares/reach*100).toFixed(1)+'%. ':'')+(Number.isFinite(prior)&&Number.isFinite(reach)?'Variação do alcance desde a leitura anterior: '+(reach-prior).toLocaleString('pt-BR')+'. ':'')+'Compare temas e formatos em períodos equivalentes. Essas medições não comprovam vendas ou causalidade.</p>';}
 function review(id){const c=data.creations.find(x=>x.id===id);if(!c)return;const local=new Date(Date.now()+300000);local.setMinutes(local.getMinutes()-local.getTimezoneOffset());openDialog('Revisar publicação · @helpumarketing',`<form id="marketing-publish" data-id="${esc(c.id)}" data-key="${crypto.randomUUID()}"><div class="internal-review-media">${c.assets.map(a=>a.mime==='video/mp4'?`<video src="${esc(a.url)}" controls></video>`:`<img src="${esc(a.url)}" alt="Arte aprovada">`).join('')}</div><label class="p-field">Legenda final<textarea name="caption" maxlength="2200" rows="6">${esc(c.caption)}</textarea></label>${c.format==='story'?'<p>Stories são enviados sem a legenda de feed.</p>':''}<label class="p-field">Data e horário (${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)})<input name="publishAt" type="datetime-local" required value="${local.toISOString().slice(0,16)}"></label><label class="checkline"><input name="confirmed" type="checkbox" required> Aprovo esta arte, legenda e horário para publicação automática exclusivamente no Instagram oficial da Helpu.</label><p role="alert" data-marketing-error></p><button class="p-button primary">Aprovar e programar</button></form>`,true);}
 document.addEventListener('click',async e=>{if(!active)return;const t=e.target.closest('[data-marketing-tab]');if(t){tab=t.dataset.marketingTab;return load();}const b=e.target.closest('[data-marketing]');if(!b)return;const action=b.dataset.marketing;if(action==='schedule')return review(b.dataset.id);if(action==='refresh')return load();b.disabled=true;try{const result=await request({action,id:b.dataset.id});if(action==='connect'){location.assign(result.url);return;}await load();toast(action==='verify'?'Conta oficial confirmada.':action==='cancel'?'Programação cancelada.':'Desempenho atualizado.');}catch(err){toast(err.message,true);}finally{b.disabled=false;}});
 document.addEventListener('submit',async e=>{if(!active||!['marketing-setup','marketing-publish'].includes(e.target.id))return;e.preventDefault();const f=e.target,b=f.querySelector('button'),v=Object.fromEntries(new FormData(f));b.disabled=true;try{if(f.id==='marketing-setup')await request({...v,action:'setup',username:'helpumarketing',confirmed:v.confirmed==='on'});else await request({...v,action:'schedule',creationId:f.dataset.id,requestId:f.dataset.key,publishAt:new Date(v.publishAt).toISOString(),confirmed:v.confirmed==='on'});closeDialog();await load();toast(f.id==='marketing-setup'?'Operação interna preparada.':'Publicação programada.');}catch(err){f.querySelector('[data-marketing-error]').textContent=err.message;}finally{b.disabled=false;}});
 return {page,mount(v){active=v==='marketing';++epoch;if(!active)creation.mount('');else load();}};
}
